50. /**
51.  * Final stage of the map generation process that encodes vector tiles using {@link VectorTile} and writes them to a
52.  * {@link WriteableTileArchive}.
53.  */
54. public class TileArchiveWriter {
55. 
56.   private static final Logger LOGGER = LoggerFactory.getLogger(TileArchiveWriter.class);
57.   private static final long MAX_FEATURES_PER_BATCH = 10_000;
58.   private static final long MAX_TILES_PER_BATCH = 1_000;
59.   private final Counter.Readable featuresProcessed;
60.   private final Counter memoizedTiles;
61.   private final WriteableTileArchive archive;
62.   private final PlanetilerConfig config;
63.   private final Stats stats;
64.   private final Counter.Readable[] tilesByZoom;
65.   private final Iterable<FeatureGroup.TileFeatures> inputTiles;
66.   private final AtomicReference<TileCoord> lastTileWritten = new AtomicReference<>();
67.   private final TileArchiveMetadata tileArchiveMetadata;
68.   private final TilesetSummaryStatistics tileStats;
69.   private final LayerAttrStats layerAttrStats = new LayerAttrStats();
70. 
71.   private TileArchiveWriter(Iterable<FeatureGroup.TileFeatures> inputTiles, WriteableTileArchive archive,
72.     PlanetilerConfig config, TileArchiveMetadata tileArchiveMetadata, Stats stats) {
73.     this.tileStats = new TilesetSummaryStatistics(TileWeights.readFromFile(config.tileWeights()));
74.     this.inputTiles = inputTiles;
75.     this.archive = archive;
76.     this.config = config;
77.     this.tileArchiveMetadata = tileArchiveMetadata;
78.     this.stats = stats;
79.     tilesByZoom = IntStream.rangeClosed(0, config.maxzoom())
80.       .mapToObj(i -> Counter.newSingleThreadCounter())
81.       .toArray(Counter.Readable[]::new);
82.     memoizedTiles = stats.longCounter("archive_memoized_tiles");
83.     featuresProcessed = stats.longCounter("archive_features_processed");
84.     Map<String, LongSupplier> countsByZoom = new LinkedHashMap<>();
85.     for (int zoom = config.minzoom(); zoom <= config.maxzoom(); zoom++) {
86.       countsByZoom.put(Integer.toString(zoom), tilesByZoom[zoom]);
87.     }
88.     stats.counter("archive_tiles_written", "zoom", () -> countsByZoom);
89.   }
90. 
91.   /** Reads all {@code features}, encodes them in parallel, and writes to {@code output}. */
92.   public static void writeOutput(FeatureGroup features, WriteableTileArchive output, DiskBacked fileSize,
93.     TileArchiveMetadata tileArchiveMetadata, Path layerStatsPath, PlanetilerConfig config, Stats stats) {
94.     var timer = stats.startStage("archive");
95. 
96.     int chunksToRead = Math.max(1, features.chunksToRead());
97.     int readThreads = Math.min(config.featureReadThreads(), chunksToRead);
98.     int threads = config.threads();
99.     int processThreads = threads < 8 ? threads : (threads - readThreads);
100.     int tileWriteThreads = config.tileWriteThreads();
101. 
102.     // when using more than 1 read thread: (N read threads) -> (1 merge thread) -> ...
103.     // when using 1 read thread we just have: (1 read & merge thread) -> ...
104.     Worker readWorker = null;
105.     Iterable<FeatureGroup.TileFeatures> inputTiles;
106.     String secondStageName;
107.     if (readThreads == 1) {
108.       secondStageName = "read";
109.       inputTiles = features;
110.     } else {
111.       secondStageName = "merge";
112.       var reader = features.parallelIterator(readThreads);
113.       inputTiles = reader.result();
114.       readWorker = reader.readWorker();
115.     }
116. 
117.     TileArchiveWriter writer = new TileArchiveWriter(inputTiles, output, config, tileArchiveMetadata, stats);
118. 
119.     var pipeline = WorkerPipeline.start("archive", stats);
120. 
121.     // a larger tile queue size helps keep cores busy, but needs a lot of RAM
122.     // 5k works fine with 100GB of RAM, so adjust the queue size down from there
123.     // but no less than 100
124.     int queueSize = Math.max(
125.       100,
126.       (int) (5_000d * ProcessInfo.getMaxMemoryBytes() / 100_000_000_000d)
127.     );
128. 
129.     /*
130.      * To emit tiles in order, fork the input queue and send features to both the encoder and writer. The writer
131.      * waits on them to be encoded in the order they were received, and the encoder processes them in parallel.
132.      * One batch might take a long time to process, so make the queues very big to avoid idle encoding CPUs.
133.      *
134.      * Note:
135.      * In the future emitting tiles out order might be especially interesting when tileWriteThreads>1,
136.      * since when multiple threads/files are included there's no order that needs to be preserved.
137.      * So some of the restrictions could be lifted then.
138.      */
139.     WorkQueue<TileBatch> writerQueue = new WorkQueue<>("archive_writer_queue", queueSize, 1, stats);
140.     WorkQueue<TileBatch> layerStatsQueue = new WorkQueue<>("archive_layerstats_queue", queueSize, 1, stats);
141.     WorkerPipeline<TileBatch> encodeBranch = pipeline
142.       .<TileBatch>fromGenerator(secondStageName, next -> {
143.         try (writerQueue; layerStatsQueue) {
144.           var writerEnqueuer = writerQueue.threadLocalWriter();
145.           var statsEnqueuer = layerStatsQueue.threadLocalWriter();
146.           writer.readFeaturesAndBatch(batch -> {
147.             next.accept(batch);
148.             writerEnqueuer.accept(batch); // also send immediately to writer
149.             if (config.outputLayerStats()) {
150.               statsEnqueuer.accept(batch);
151.             }
152.           });
153.         }
154.         // use only 1 thread since readFeaturesAndBatch needs to be single-threaded
155.       }, 1)
156.       .addBuffer("reader_queue", queueSize)
157.       .sinkTo("encode", processThreads, writer::tileEncoderSink);
158. 
159.     // ensure to initialize the archive BEFORE starting to write any tiles
160.     output.initialize();
161. 
162.     // the tile writer will wait on the result of each batch to ensure tiles are written in order
163.     WorkerPipeline<TileBatch> writeBranch = pipeline.readFromQueue(writerQueue)
164.       .sinkTo("write", tileWriteThreads, writer::tileWriter);
165. 
166.     WorkerPipeline<TileBatch> layerStatsBranch = null;
167. 
168.     if (config.outputLayerStats()) {
169.       layerStatsBranch = pipeline.readFromQueue(layerStatsQueue)
170.         .sinkTo("stats", 1, tileStatsWriter(layerStatsPath));
171.     }
172. 
173.     var loggers = ProgressLoggers.create()
174.       .addRatePercentCounter("features", features.numFeaturesWritten(), writer.featuresProcessed, true)
175.       .addFileSize(features)
176.       .addRateCounter("tiles", writer::tilesEmitted)
177.       .addFileSize(fileSize)
178.       .newLine()
179.       .addProcessStats()
180.       .newLine();
181.     if (readWorker != null) {
182.       loggers.addThreadPoolStats("read", readWorker);
183.     }
184.     loggers.addPipelineStats(encodeBranch)
185.       .addPipelineStats(writeBranch);
186.     if (layerStatsBranch != null) {
187.       loggers.addPipelineStats(layerStatsBranch);
188.     }
189.     loggers.newLine()
190.       .add(writer::getLastTileLogDetails);
191. 
192.     final CompletableFuture<Void> tileWritersFuture = writeBranch.done();
193.     final CompletableFuture<Void> layerStatsFuture =
194.       layerStatsBranch == null ? CompletableFuture.completedFuture(null) : layerStatsBranch.done();
195.     final CompletableFuture<Void> archiveFinisher =
196.       CompletableFuture.allOf(tileWritersFuture, layerStatsFuture).thenRun(writer::finishArchive);
197. 
198.     var doneFuture = joinFutures(tileWritersFuture, layerStatsFuture, encodeBranch.done(), archiveFinisher);
199.     loggers.awaitAndLog(doneFuture, config.logInterval());
200.     writer.printTileStats();
201.     timer.stop();
202.   }
203. 
204.   private static WorkerPipeline.SinkStep<TileBatch> tileStatsWriter(Path layerStatsPath) {
205.     return prev -> {
206.       try (var statsWriter = TileSizeStats.newWriter(layerStatsPath)) {
207.         statsWriter.write(TileSizeStats.headerRow());
208.         for (var batch : prev) {
209.           for (var encodedTile : batch.out().get()) {
210.             for (var line : encodedTile.layerStats()) {
211.               statsWriter.write(line);
212.             }
213.           }
214.         }
215.       }
216.     };
217.   }
218. 
219.   private String getLastTileLogDetails() {
220.     TileCoord lastTile = lastTileWritten.get();
221.     String blurb;
222.     if (lastTile == null) {
223.       blurb = "n/a";
224.     } else {
225.       blurb = "%d/%d/%d (z%d %s) %s".formatted(
226.         lastTile.z(), lastTile.x(), lastTile.y(),
227.         lastTile.z(),
228.         Format.defaultInstance().percent(archive.tileOrder().progressOnLevel(lastTile, config.bounds().tileExtents())),
229.         lastTile.getDebugUrl(config.debugUrlPattern())
230.       );
231.     }
232.     return "last tile: " + blurb;
233.   }
234. 
235.   private void readFeaturesAndBatch(Consumer<TileBatch> next) {
236.     int currentZoom = Integer.MIN_VALUE;
237.     TileBatch batch = new TileBatch();
238.     long featuresInThisBatch = 0;
239.     long tilesInThisBatch = 0;
240.     for (var feature : inputTiles) {
241.       int z = feature.tileCoord().z();
242.       if (z != currentZoom) {
243.         LOGGER.trace("Starting z{}", z);
244.         currentZoom = z;
245.       }
246.       long thisTileFeatures = feature.getNumFeaturesToEmit();
247.       if (tilesInThisBatch > 0 &&
248.         (tilesInThisBatch >= MAX_TILES_PER_BATCH ||
249.           ((featuresInThisBatch + thisTileFeatures) > MAX_FEATURES_PER_BATCH))) {
250.         next.accept(batch);
251.         batch = new TileBatch();
252.         featuresInThisBatch = 0;
253.         tilesInThisBatch = 0;
254.       }
255.       featuresInThisBatch += thisTileFeatures;
256.       tilesInThisBatch++;
257.       batch.in.add(feature);
258.     }
259.     if (!batch.in.isEmpty()) {
260.       next.accept(batch);
261.     }
262.   }
263. 
264.   private void tileEncoderSink(Iterable<TileBatch> prev) throws IOException {
265.     /*
266.      * To optimize emitting many identical consecutive tiles (like large ocean areas), memoize output to avoid
267.      * recomputing if the input hasn't changed.
268.      */
269.     byte[] lastBytes = null, lastEncoded = null;
270.     Long lastTileDataHash = null;
271.     boolean lastIsFill = false;
272.     List<TileSizeStats.LayerStats> lastLayerStats = null;
273.     boolean skipFilled = config.skipFilledTiles();
274.     var layerStatsSerializer = TileSizeStats.newThreadLocalSerializer();
275. 
276.     var tileStatsUpdater = tileStats.threadLocalUpdater();
277.     var layerAttrStatsUpdater = layerAttrStats.handlerForThread();
278.     for (TileBatch batch : prev) {
279.       List<TileEncodingResult> result = new ArrayList<>(batch.size());
280.       FeatureGroup.TileFeatures last = null;
281.       // each batch contains tile ordered by tile-order ID ascending
282.       for (int i = 0; i < batch.in.size(); i++) {
283.         FeatureGroup.TileFeatures tileFeatures = batch.in.get(i);
284.         featuresProcessed.incBy(tileFeatures.getNumFeaturesProcessed());
285.         byte[] bytes, encoded;
286.         List<TileSizeStats.LayerStats> layerStats;
287.         Long tileDataHash;
288.         if (tileFeatures.hasSameContents(last)) {
289.           bytes = lastBytes;
290.           encoded = lastEncoded;
291.           tileDataHash = lastTileDataHash;
292.           layerStats = lastLayerStats;
293.           memoizedTiles.inc();
294.         } else {
295.           VectorTile tile = tileFeatures.getVectorTile(layerAttrStatsUpdater);
296.           if (tile.isEmpty()) {
297.             continue;
298.           } else if ((skipFilled && (lastIsFill = tile.containsOnlyFills()))) {
299.             encoded = null;
300.             layerStats = null;
301.             bytes = null;
302.           } else {
303.             encoded = switch (config.tileFormat()) {
304.               case MLT -> {
305.                 MapboxVectorTile mltInput = tile.toMltInput(stats);
306.                 List<ColumnMapping> columnMappings = List.of();
307.                 var tilesetMetadata = MltConverter.createTilesetMetadata(mltInput, columnMappings, true, true, false);
308.                 Map<String, FeatureTableOptimizations> optimizations = Map.of();
309.                 var conversionConfig = new ConversionConfig(
310.                   true,
311.                   config.mltAdvanced(),
312.                   /* coercePropertyValues= */ true,
313.                   optimizations,
314.                   /* preTessellatePolygons= */ false,
315.                   /* useMortonEncoding= */ true,
316.                   /* outlineFeatureTableNames= */ null);
317.                 var mlt = MltConverter.convertMvt(mltInput, tilesetMetadata, conversionConfig, null);
318.                 layerStats = TileSizeStats.computeMltTileStats(tile, mltInput, mlt);
319.                 yield mlt;
320.               }
321.               case UNKNOWN, MVT -> {
322.                 var proto = tile.toProto();
323.                 layerStats = TileSizeStats.computeTileStats(proto);
324.                 yield proto.toByteArray();
325.               }
326.             };
327.             bytes = switch (config.tileCompression()) {
328.               case GZIP -> gzip(encoded);
329.               case NONE -> encoded;
330.               case UNKNOWN -> throw new IllegalArgumentException("cannot compress \"UNKNOWN\"");
331.             };
332.             if (encoded.length > config.tileWarningSizeBytes()) {
333.               LOGGER.warn("{} {}kb uncompressed",
334.                 tileFeatures.tileCoord(),
335.                 encoded.length / 1024);
336.             }
337.           }
338.           lastLayerStats = layerStats;
339.           lastEncoded = encoded;
340.           lastBytes = bytes;
341.           last = tileFeatures;
342.           if (archive.deduplicates() && tile.likelyToBeDuplicated() && bytes != null) {
343.             tileDataHash = generateContentHash(bytes);
344.           } else {
345.             tileDataHash = null;
346.           }
347.           lastTileDataHash = tileDataHash;
348.         }
349.         if (!(skipFilled && lastIsFill) && bytes != null) {
350.           tileStatsUpdater.recordTile(tileFeatures.tileCoord(), bytes.length, layerStats);
351.           List<String> layerStatsRows = config.outputLayerStats() ?
352.             layerStatsSerializer.formatOutputRows(tileFeatures.tileCoord(), bytes.length, layerStats) :
353.             List.of();
354.           result.add(
355.             new TileEncodingResult(
356.               tileFeatures.tileCoord(),
357.               bytes,
358.               encoded.length,
359.               tileDataHash == null ? OptionalLong.empty() : OptionalLong.of(tileDataHash),
360.               layerStatsRows
361.             )
362.           );
363.         }
364.       }
365.       // hand result off to writer
366.       batch.out.complete(result);
367.     }
368.   }
369. 
370.   private final AtomicBoolean firstTileWriterTracker = new AtomicBoolean(true);
371. 
372.   private void tileWriter(Iterable<TileBatch> tileBatches) throws ExecutionException, InterruptedException {
373. 
374.     final boolean firstTileWriter = firstTileWriterTracker.compareAndExchange(true, false);
375. 
376.     var f = NumberFormat.getNumberInstance(Locale.getDefault());
377.     f.setMaximumFractionDigits(5);
378. 
379.     var order = archive.tileOrder();
380. 
381.     TileCoord lastTile = null;
382.     Timer time = null;
383.     int currentZ = Integer.MIN_VALUE;
384.     try (var tileWriter = archive.newTileWriter()) {
385.       for (TileBatch batch : tileBatches) {
386.         for (var encodedTile : batch.out.get()) {
387.           TileCoord tileCoord = encodedTile.coord();
388.           assert lastTile == null ||
389.             order.encode(tileCoord) > order.encode(lastTile) : "Tiles out of order %s before %s"
390.               .formatted(lastTile, tileCoord);
391.           lastTile = encodedTile.coord();
392.           int z = tileCoord.z();
393.           if (z != currentZ) {
394.             // for multiple writers the starting/finish log message of the _first_ tilewriter
395.             // is not 100% accurate in terms of overall "zoom-progress",
396.             // but it should be a "good-enough" indicator for "zoom-progress"-logging
397.             if (firstTileWriter) {
398.               if (time == null) {
399.                 LOGGER.info("Starting z{}", z);
400.               } else {
401.                 LOGGER.info("Finished z{} in {}, now starting z{}", currentZ, time.stop(), z);
402.               }
403.             }
404.             time = Timer.start();
405.             currentZ = z;
406.           }
407.           tileWriter.write(encodedTile);
408. 
409.           stats.wroteTile(z, encodedTile.tileData().length);
410.           tilesByZoom[z].inc();
411.         }
412.         lastTileWritten.set(lastTile);
413.       }
414.       tileWriter.printStats();
415.     }
416. 
417.     if (time != null) {
418.       LOGGER.info("Finished z{} in {}", currentZ, time.stop());
419.     }
420.   }
421. 
422.   @SuppressWarnings("java:S2629")
423.   private void printTileStats() {
424.     Format format = Format.defaultInstance();
425.     tileStats.printStats(config.debugUrlPattern());
426.     LOGGER.debug(" # features: {}", format.integer(featuresProcessed.get()));
427.   }
428. 
429.   private long tilesEmitted() {
430.     return Stream.of(tilesByZoom).mapToLong(c -> c.get()).sum();
431.   }
432. 
433.   private void finishArchive() {
434.     archive.finish(tileArchiveMetadata.withLayerStats(layerAttrStats.getTileStats()));
435.   }
436. 
437.   /**
438.    * Generates a hash over encoded and compressed tile.
439.    * <p>
440.    * Used as an optimization to avoid writing the same (mostly ocean) tiles over and over again.
441.    */
442.   public static long generateContentHash(byte[] bytes) {
443.     return Hashing.fnv1a64(bytes);
444.   }
445. 
446.   /**
447.    * Container for a batch of tiles to be processed together in the encoder and writer threads.
448.    * <p>
449.    * The cost of encoding a tile may vary dramatically by its size (depending on the profile) so batches are sized
450.    * dynamically to put as little as 1 large tile, or as many as 10,000 small tiles in a batch to keep encoding threads
451.    * busy.
452.    *
453.    * @param in  the tile data to encode
454.    * @param out the future that encoder thread completes to hand finished tile off to writer thread
455.    */
456.   private record TileBatch(
457.     List<FeatureGroup.TileFeatures> in,
458.     CompletableFuture<List<TileEncodingResult>> out
459.   ) {
460. 
461.     TileBatch() {
462.       this(new ArrayList<>(), new CompletableFuture<>());
463.     }
464. 
465.     public int size() {
466.       return in.size();
467.     }
468. 
469.     public boolean isEmpty() {
470.       return in.isEmpty();
471.     }
472.   }
473. }
