       .addRateCounter("tiles", counter)
       .newLine()
       .addPipelineStats(readBranch)
       .addPipelineStats(writeBranch)
       .newLine()
       .addProcessStats();
     loggers.awaitAndLog(joinFutures(readBranch.done(), writeBranch.done()), config.logInterval());

