       for (var layer : layerStats) {
         result.add(writer.writeValueAsString(new OutputRow(
           tileCoord.z(),
           tileCoord.x(),
           tileCoord.y(),
           hilbert,
           archivedBytes,
           layer.layer,
           layer.layerBytes,
           layer.layerFeatures,
           layer.layerGeometries,
           layer.layerAttrBytes,
           layer.layerAttrKeys,
           layer.layerAttrValues
